     5→import * as ActionSheetAwareScrollView from '@components/ActionSheetAwareScrollView';
     6→import type {PopoverAnchorPosition} from '@components/Modal/types';
     7→import Popover from '@components/Popover';
     8→import usePrevious from '@hooks/usePrevious';
     9→import useSidePanel from '@hooks/useSidePanel';
    10→import useThemeStyles from '@hooks/useThemeStyles';
    11→import useWindowDimensions from '@hooks/useWindowDimensions';
    12→import ComposerFocusManager from '@libs/ComposerFocusManager';
    13→import PopoverWithMeasuredContentUtils from '@libs/PopoverWithMeasuredContentUtils';
    14→import variables from '@styles/variables';
    15→import CONST from '@src/CONST';
    16→import type PopoverWithMeasuredContentProps from './types';
    17→
    18→/**
    19→ * This is a convenient wrapper around the regular Popover component that allows us to use a more sophisticated
    20→ * positioning schema responsively (without having to provide a static width and height for the popover content).
    21→ * This way, we can shift the position of popover so that the content is anchored where we want it relative to the
    22→ * anchor position.
    23→ */
    24→
    25→function PopoverWithMeasuredContentBase({
    26→    popoverDimensions = {
    27→        width: CONST.POPOVER_DROPDOWN_WIDTH,
    28→        height: CONST.POPOVER_DROPDOWN_MIN_HEIGHT,
    29→    },
    30→    anchorPosition,
    31→    isVisible,
    32→    anchorAlignment = {
    33→        horizontal: CONST.MODAL.ANCHOR_ORIGIN_HORIZONTAL.LEFT,
    34→        vertical: CONST.MODAL.ANCHOR_ORIGIN_VERTICAL.BOTTOM,
    35→    },
    36→    children,
    37→    withoutOverlay = false,
    38→    fullscreen = true,
    39→    shouldSetModalVisibility = true,
    40→    statusBarTranslucent = true,
    41→    navigationBarTranslucent = true,
    42→    avoidKeyboard = false,
    43→    hideModalContentWhileAnimating = false,
    44→    anchorDimensions = {
    45→        height: 0,
    46→        width: 0,
    47→    },
    48→    shouldSwitchPositionIfOverflow = false,
    49→    shouldHandleNavigationBack = false,
    50→    shouldEnableNewFocusManagement,
    51→    shouldMeasureAnchorPositionFromTop = false,
    52→    shouldSkipRemeasurement = false,
    53→    ...props
    54→}: PopoverWithMeasuredContentProps) {
    55→    const actionSheetAwareScrollViewContext = useContext(ActionSheetAwareScrollView.ActionSheetAwareScrollViewContext);
    56→    const styles = useThemeStyles();
    57→    const {windowWidth, windowHeight} = useWindowDimensions();
    58→    const [popoverWidth, setPopoverWidth] = useState(popoverDimensions.width);
    59→    const [popoverHeight, setPopoverHeight] = useState(popoverDimensions.height);
    60→    const [isContentMeasured, setIsContentMeasured] = useState(popoverWidth > 0 && popoverHeight > 0);
    61→    const prevIsVisible = usePrevious(isVisible);
    62→    const prevAnchorPosition = usePrevious(anchorPosition);
    63→    const {shouldHideSidePanel} = useSidePanel();
    64→    const availableWidth = windowWidth - (shouldHideSidePanel ? 0 : variables.sideBarWidth);
    65→    const prevWindowDimensions = usePrevious({availableWidth, windowHeight});
    66→
    67→    const hasStaticDimensions = popoverDimensions.width > 0 && popoverDimensions.height > 0;
    68→    const modalId = useMemo(() => ComposerFocusManager.getId(), []);
    69→
    70→    useEffect(() => {
    71→        if (prevIsVisible || !isVisible || !shouldEnableNewFocusManagement) {
    72→            return;
    73→        }
    74→        ComposerFocusManager.saveFocusState(modalId);
    75→    }, [isVisible, shouldEnableNewFocusManagement, prevIsVisible, modalId]);
    76→
    77→    if (!prevIsVisible && isVisible && isContentMeasured && !shouldSkipRemeasurement) {
    78→        // Check if anything significant changed that would require re-measurement
    79→        const hasAnchorPositionChanged = !deepEqual(prevAnchorPosition, anchorPosition);
    80→        const hasWindowSizeChanged = !deepEqual(prevWindowDimensions, {availableWidth, windowHeight});
    81→
    82→        // Only reset if:
    83→        // 1. We don't have static dimensions, OR
    84→        // 2. The anchor position changed significantly, OR
    85→        // 3. The window size changed significantly
    86→        if (!hasStaticDimensions || hasAnchorPositionChanged || hasWindowSizeChanged) {
    87→            setIsContentMeasured(false);
    88→        }
    89→    }
    90→
    91→    /**
    92→     * Measure the size of the popover's content.
    93→     */
    94→    const measurePopover = ({nativeEvent}: LayoutChangeEvent) => {
    95→        const {width, height} = nativeEvent.layout;
    96→        if (width !== 0 && !hasStaticDimensions) {
    97→            setPopoverWidth(width);
    98→        }
    99→        if (height !== 0 && !hasStaticDimensions) {
   100→            setPopoverHeight(height);
   101→        }
   102→        setIsContentMeasured(true);
   103→
   104→        // it handles the case when `measurePopover` is called with values like: 192, 192.00003051757812, 192
